() => {
  const btns = Array.from(document.querySelectorAll('button'));
  const matches = btns.map(b => ({
    text: (b.innerText || '').trim().slice(0, 50),
    title: b.getAttribute('title') || '',
    aria: b.getAttribute('aria-label') || '',
    cls: (b.className || '').slice(0, 80)
  })).filter(b => b.text.includes('报告') || b.title.includes('报告') || b.aria.includes('报告'));
  return matches;
}

() => {
  const all = Array.from(document.querySelectorAll('*'));
  const matches = all.filter(el => el.children.length === 0 && (el.textContent || '').includes('报告模式'))
    .map(el => ({ tag: el.tagName, text: (el.textContent || '').trim().slice(0, 60), cls: (el.className.baseVal !== undefined ? el.className.baseVal : el.className || '').toString().slice(0, 100) }));
  // also search title attributes
  const titled = Array.from(document.querySelectorAll('[title*="报告"], [aria-label*="报告"]')).map(el => ({ tag: el.tagName, title: el.getAttribute('title'), aria: el.getAttribute('aria-label') }));
  return { matches, titled };
}

