async () => {
  const res = await fetch('/api/datasources', { credentials: 'include' });
  if (!res.ok) return { status: res.status };
  const data = await res.json();
  return (data.dataSources || data || []).map(ds => ({ id: ds.id, name: ds.name, type: ds.type, rowCount: ds.rowCount }));
}

async () => {
  const keys = Object.keys(localStorage);
  const tokenKey = keys.find(k => k.toLowerCase().includes('token') || k.toLowerCase().includes('auth'));
  const token = tokenKey ? localStorage.getItem(tokenKey) : null;
  if (!token) return { keys };
  const res = await fetch('/api/datasources', { headers: { 'Authorization': 'Bearer ' + token } });
  if (!res.ok) return { status: res.status, tokenKey };
  const data = await res.json();
  const list = data.dataSources || data.items || data || [];
  return { tokenKey, sources: list.map(ds => ({ id: ds.id, name: ds.name, type: ds.type })) };
}

async () => {
  const keys = Object.keys(localStorage);
  const tokenKey = keys.find(k => k.toLowerCase().includes('token') || k.toLowerCase().includes('auth'));
  let token = tokenKey ? localStorage.getItem(tokenKey) : null;
  if (token) { try { token = JSON.parse(token); } catch(e) {} }
  if (!token) return { keys };
  const res = await fetch('/api/datasources', { headers: { 'Authorization': 'Bearer ' + String(token) } });
  if (!res.ok) return { status: res.status, tokenKey };
  const data = await res.json();
  const list = data.dataSources || data.items || data || [];
  return { tokenKey, sources: list.map(ds => ({ id: ds.id, name: ds.name, type: ds.type })) };
}

() => {
  const raw = localStorage.getItem('auth-store');
  try { const parsed = JSON.parse(raw); return { keys: Object.keys(parsed), stateKeys: parsed.state ? Object.keys(parsed.state) : null }; } catch(e) { return { raw: (raw || '').slice(0, 200) }; }
}

async () => {
  const raw = localStorage.getItem('auth-store');
  const parsed = JSON.parse(raw);
  const token = parsed.state.token;
  const res = await fetch('/api/datasources', { headers: { 'Authorization': 'Bearer ' + token } });
  if (!res.ok) return { status: res.status };
  const data = await res.json();
  const list = data.dataSources || data.items || data || [];
  return { sources: list.map(ds => ({ id: ds.id, name: ds.name, type: ds.type })) };
}

async () => {
  const token = JSON.parse(localStorage.getItem('auth-store')).state.token;
  const ids = ['ds_pg_analytics', 'ds_1786406744499', 'ds_1786620486498', 'ds_enterprise_demo'];
  const out = {};
  for (const id of ids) {
    try {
      const res = await fetch(`/api/datasources/${id}/schema`, { headers: { 'Authorization': 'Bearer ' + token } });
      if (!res.ok) { out[id] = { status: res.status }; continue; }
      const data = await res.json();
      const tables = data.tables || data.schema || [];
      out[id] = tables.map(t => ({ name: t.name || t.tableName, cols: (t.columns || []).map(c => c.name || c.columnName).slice(0, 30) }));
    } catch (e) { out[id] = { error: String(e) }; }
  }
  return out;
}

