input.function:
() => {
  const cells = Array.from(document.querySelectorAll('main *')).filter(el => el.children.length === 0 && el.textContent === '企业战略决策简报');
  if (cells[0]) cells[0].scrollIntoView({ block: 'center' });
  const btn = Array.from(document.querySelectorAll('main button')).find(b => b.textContent.includes('预设模板不可编辑'));
  const rect = btn ? btn.getBoundingClientRect() : null;
  return { scrolled: cells.length > 0, editBtnVisible: rect ? { x: rect.x, y: rect.y, w: rect.width, disabled: btn.disabled } : null };
}

() => {
  const btns = Array.from(document.querySelectorAll('main button'));
  const editBtns = btns.filter(b => (b.textContent || '').includes('不可编辑'));
  const delBtns = btns.filter(b => (b.textContent || '').includes('不可删除'));
  return {
    editCount: editBtns.length,
    editAllDisabled: editBtns.every(b => b.disabled),
    delCount: delBtns.length,
    delAllDisabled: delBtns.every(b => b.disabled),
    firstEditRect: editBtns[0] ? editBtns[0].getBoundingClientRect().toJSON() : null
  };
}

() => {
  const btns = Array.from(document.querySelectorAll('main button'));
  return btns.map(b => ({
    text: (b.innerText || b.textContent || '').trim().slice(0, 20),
    title: b.getAttribute('title') || '',
    disabled: b.disabled
  }));
}

() => {
  const btn = Array.from(document.querySelectorAll('main button')).find(b => b.getAttribute('title') === '预设模板不可删除');
  if (btn) btn.scrollIntoView({ block: 'center', inline: 'end' });
  return { ok: !!btn };
}
